-- 008_paper_release: release-backed fixed/random training papers and immutable candidate snapshots.
-- Existing rows remain regulation-scoped legacy fixed papers.

-- @step extend_exam_paper_release_config
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper') = 19 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND ((COLUMN_NAME = 'regulation_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'business_scope' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'regulation') OR (COLUMN_NAME = 'mode' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'fixed') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids', 'rule_config') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL))) = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND INDEX_NAME = 'idx_paper_training_pool' AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'business_scope') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'mode') OR (SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status')) AND NON_UNIQUE = 1 AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `exam_paper` MODIFY COLUMN `regulation_id` BIGINT UNSIGNED NULL COMMENT '制度专项卷所属制度；培训卷为 NULL', ADD COLUMN `business_scope` VARCHAR(16) NOT NULL DEFAULT 'regulation' COMMENT 'regulation / training' AFTER `regulation_id`, ADD COLUMN `mode` VARCHAR(16) NOT NULL DEFAULT 'fixed' COMMENT 'fixed / random' AFTER `business_scope`, ADD COLUMN `category_id` BIGINT UNSIGNED NULL COMMENT '培训卷类别；制度专项卷为 NULL' AFTER `mode`, ADD COLUMN `requires_learning` TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '培训卷默认 0；制度专项卷保持 1' AFTER `category_id`, ADD COLUMN `regulation_ids` JSON NULL COMMENT '培训卷可选制度筛选；空数组表示不过滤' AFTER `requires_learning`, ADD COLUMN `course_ids` JSON NULL COMMENT '课程说明关联，不参与抽题过滤' AFTER `regulation_ids`, ADD COLUMN `rule_config` JSON NULL COMMENT '草稿题型、题量与整数分配置' AFTER `course_ids`, ADD KEY `idx_paper_training_pool` (`category_id`, `business_scope`, `mode`, `status`);

-- @step extend_paper_question_version
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_question') = 7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_question' AND ((COLUMN_NAME = 'question_version_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'concept_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL))) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_question' AND ((INDEX_NAME = 'idx_paper_question_version' AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'question_version_id') OR (INDEX_NAME = 'idx_paper_question_concept' AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'concept_id')) AND NON_UNIQUE = 1 AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `paper_question` ADD COLUMN `question_version_id` BIGINT UNSIGNED NULL COMMENT '培训固定卷选定的当前审核版本；legacy 为 NULL' AFTER `question_id`, ADD COLUMN `concept_id` BIGINT UNSIGNED NULL COMMENT '发布前重复考点校验快照' AFTER `question_version_id`, ADD KEY `idx_paper_question_version` (`question_version_id`), ADD KEY `idx_paper_question_concept` (`concept_id`);

-- @step create_paper_release
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release') = 12 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('paper_id', 'created_by') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'version_no' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('business_scope', 'mode') AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'released_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED'))) = 12 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id') OR (INDEX_NAME = 'uk_paper_release_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (INDEX_NAME = 'uk_paper_release_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'version_no') OR (INDEX_NAME = 'idx_paper_release_category' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `paper_release` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `paper_id` BIGINT UNSIGNED NOT NULL, `version_no` INT UNSIGNED NOT NULL, `business_scope` VARCHAR(16) NOT NULL, `mode` VARCHAR(16) NOT NULL, `category_id` BIGINT UNSIGNED NULL, `requires_learning` TINYINT UNSIGNED NOT NULL DEFAULT 0, `rule_snapshot` JSON NOT NULL, `regulation_ids` JSON NULL, `course_ids` JSON NULL, `created_by` BIGINT UNSIGNED NOT NULL, `released_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_paper_release_version` (`paper_id`, `version_no`), KEY `idx_paper_release_category` (`category_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='不可变试卷发布版本';

-- @step create_paper_release_question
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release_question' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release_question') = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release_question' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('release_id', 'question_id', 'question_version_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'concept_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'difficulty') AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('score_cents', 'position') AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'snapshot_json' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO'))) = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release_question') = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release_question' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id') OR (INDEX_NAME = 'uk_release_question_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'release_id') OR (INDEX_NAME = 'uk_release_question_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'question_version_id') OR (INDEX_NAME = 'idx_release_question_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'release_id') OR (INDEX_NAME = 'idx_release_question_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'difficulty') OR (INDEX_NAME = 'idx_release_question_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'type')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 6 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `paper_release_question` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `release_id` BIGINT UNSIGNED NOT NULL, `question_id` BIGINT UNSIGNED NOT NULL, `question_version_id` BIGINT UNSIGNED NOT NULL, `concept_id` BIGINT UNSIGNED NULL, `type` VARCHAR(16) NOT NULL, `difficulty` VARCHAR(16) NOT NULL, `score_cents` INT UNSIGNED NOT NULL, `position` INT UNSIGNED NOT NULL DEFAULT 0, `snapshot_json` JSON NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_release_question_version` (`release_id`, `question_version_id`), KEY `idx_release_question_pool` (`release_id`, `difficulty`, `type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='发布时冻结的候选题版本与实际分值';
